-- Service-read delegate: receipt-derived owned facts and episode denial; no fixture persists.
DO $$ DECLARE run text:=replace(gen_random_uuid()::text,'-',''); cid text:='sr-'||run;kid text:='srk-'||run;actor uuid:=gen_random_uuid();inst text:='vi-sr-'||run;ep text:='ep-sr-'||run;vin text:='DEVSYNSR'||upper(substr(run,1,9));e jsonb;q jsonb;raw text;r jsonb;n int;passed int:=0;f text;
BEGIN
 INSERT INTO gw_tenant_members(user_id,tenant_id,role) VALUES(actor,'grp-syn-northwind','admin');PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 e:=jsonb_build_object('event_id',gen_random_uuid(),'schema_version',1,'tenant_id','grp-syn-northwind','rooftop_id','rt-syn-nw-01','source_app','autocurb','event_type','appraisal.completed','aggregate',jsonb_build_object('type','vehicle_instance','id',inst,'revision',1),'vehicle',jsonb_build_object('vin',vin,'instance_id',inst,'episode_id',ep),'occurred_at',clock_timestamp(),'emitted_at',clock_timestamp(),'payload',jsonb_build_object('acv_value',101,'acv_cents',102,'offered_price',103,'finance_amount',104,'nested',jsonb_build_object('finance_amount',105)));
 r:=gw_publish(e);FOR n IN 1..4 LOOP PERFORM gw_worker_step('sr-reader',100,50);END LOOP;
 INSERT INTO gw_service_stage_gates VALUES(1,true,true,true,true,'rollback-only') ON CONFLICT(id) DO UPDATE SET enabled=true,audience_reviewed=true,threat_reviewed=true,private_transport=true;
 INSERT INTO gw_service_connections(connection_id,app,tenant_id,rooftop_ids,endpoint_ref,network_allowlist,provisioned_by,enabled) VALUES(cid,'autofilm','grp-syn-northwind',ARRAY['rt-syn-nw-01'],'local-test:'||cid,ARRAY['127.0.0.1'::inet],actor,true);
 INSERT INTO gw_service_keys(key_id,connection_id,fingerprint,key_role,directions,owners,purposes,not_before,not_after,rotate_after,budget_per_min) VALUES(kid,cid,repeat('a',64),'fact_reader',ARRAY['authorized_pull'],ARRAY['autocurb']::gw_app[],ARRAY['acquisition_context'],clock_timestamp()-interval '1 minute',clock_timestamp()+interval '1 hour',clock_timestamp()+interval '30 minutes',120);
 q:=jsonb_build_object('protocol','gw.service-staging/1','app','autofilm','direction','authorized_pull','tenant','grp-syn-northwind','rooftop','rt-syn-nw-01','body',jsonb_build_object('tenant','grp-syn-northwind','rooftop','rt-syn-nw-01','source_app','autocurb','purpose','acquisition_context','lookups',jsonb_build_array(jsonb_build_object('vin',vin,'instance_id',inst))));raw:=q::text;
 r:=gw_service_execute(kid,repeat('a',64),'service-read-positive-001',clock_timestamp(),raw,encode(extensions.digest(raw,'sha256'),'hex'),'127.0.0.1');IF r->>'decision' IS DISTINCT FROM 'ok' OR (r->'data'->'items'->0->'facts'->'acquisition'->>'appraisal_completed')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'SERVICE_READ_FAILED: %',r->>'reason';END IF;passed:=passed+1;
 FOREACH f IN ARRAY ARRAY['acv_value','acv_cents','offered_price','finance_amount'] LOOP IF r::text LIKE '%'||f||'%' THEN RAISE EXCEPTION 'SERVICE_READ_ACV';END IF;passed:=passed+1;END LOOP;
 INSERT INTO gw_listing_episodes(id,tenant_id,instance_id,opened_at) VALUES('ep-sr-new-'||run,'grp-syn-northwind',inst,clock_timestamp()+interval '1 second');
 r:=gw_service_execute(kid,repeat('a',64),'service-read-episode-001',clock_timestamp(),raw,encode(extensions.digest(raw,'sha256'),'hex'),'127.0.0.1');IF (r->'data'->'items'->0->'facts'->'acquisition'->>'appraisal_completed')::boolean IS DISTINCT FROM false OR r->'data'->'items'->0->'facts'->'acquisition' ? 'audit_ref' OR r->'data'->'items'->0->'facts'->'acquisition' ? 'completed_at' THEN RAISE EXCEPTION 'SERVICE_READ_PRIOR_EPISODE';END IF;passed:=passed+1;
 UPDATE gw_service_keys SET budget_per_min=2 WHERE key_id=kid;
 r:=gw_service_execute(kid,repeat('a',64),'service-read-rate-00001',clock_timestamp(),raw,encode(extensions.digest(raw,'sha256'),'hex'),'127.0.0.1');IF (r->>'http_status')::int IS DISTINCT FROM 429 THEN RAISE EXCEPTION 'SERVICE_READ_RATE';END IF;passed:=passed+1;
 RAISE EXCEPTION 'GW_TESTS_PASSED: %',passed;
END $$;